import React, { useState } from 'react';
import { Header } from './components/Header';
import { TelemetryStrip } from './components/TelemetryStrip';
import { Viewport3D } from './components/Viewport3D';
import { JogControlPanel } from './components/panels/JogControlPanel';
import { CartesianControlPanel } from './components/panels/CartesianControlPanel';
import { TrajectoryControlPanel } from './components/panels/TrajectoryControlPanel';
import { FATSuitePanel } from './components/panels/FATSuitePanel';
import { BlackboxPanel } from './components/panels/BlackboxPanel';

import { useArmSimulation, INITIAL_ANGLES } from './hooks/useArmSimulation';
import { roboticSound } from './services/soundEngine';
import { PRESET_PROGRAMS } from './services/presetPrograms';

import { Vector3D } from './types/arm';
import { ControlMode, ServoState } from './types/telemetry';
import { TrajectoryProgram } from './types/trajectory';

export const App: React.FC = () => {
  const [servoState, setServoState] = useState<ServoState>('ENGAGED');
  const [controlMode, setControlMode] = useState<ControlMode>('JOG');
  const [isAudioMuted, setIsAudioMuted] = useState(true);
  const [cycleCount, setCycleCount] = useState(1);

  const [targetAngles, setTargetAngles] = useState<number[]>([...INITIAL_ANGLES]);
  const [gripperWidth, setGripperWidth] = useState(60.0);
  const [targetPos, setTargetPos] = useState<Vector3D>({ x: 380, y: 180, z: 0 });
  const [targetPitch, setTargetPitch] = useState(0);

  const [activeProgram, setActiveProgram] = useState<TrajectoryProgram>(PRESET_PROGRAMS[0]);
  const [ikConverged, setIkConverged] = useState(true);
  const [ikErrorMm, setIkErrorMm] = useState(0.0);

  const {
    kinematics,
    dynamics,
    gripper,
    trajectory,
    testRunner,
    positions,
    tcpPose,
    workpieces,
    telemetry,
    activeWaypoint,
    trajProgress,
    activeScenario,
  } = useArmSimulation({
    servoState,
    controlMode,
    targetAngles,
    gripperWidth,
    targetPos,
    targetPitch,
    activeProgram,
    cycleCount,
  });

  const handleToggleServo = () => {
    if (servoState === 'ESTOP') return;
    setServoState((prev) => (prev === 'ENGAGED' ? 'DISENGAGED' : 'ENGAGED'));
  };

  const handleToggleEStop = () => {
    if (servoState === 'ESTOP') {
      setServoState('DISENGAGED');
    } else {
      setServoState('ESTOP');
      trajectory.pause();
    }
  };

  const handleResetHome = () => {
    dynamics.resetToHome();
    gripper.reset();
    trajectory.stop();
    setTargetAngles([...INITIAL_ANGLES]);
    setGripperWidth(60);
    setCycleCount((c) => c + 1);
    setControlMode('JOG');
  };

  const handleToggleAudio = () => {
    const nextMute = !isAudioMuted;
    setIsAudioMuted(nextMute);
    roboticSound.setMute(nextMute);
  };

  const handleSolveIK = () => {
    const actual = dynamics.getActualAngles();
    const res = kinematics.inverseKinematics(targetPos, actual, targetPitch);
    setIkConverged(res.converged);
    setIkErrorMm(res.errorMm);
    if (res.converged) setTargetAngles([...res.anglesDeg]);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', background: 'var(--bg-primary)' }}>
      <Header
        telemetry={telemetry}
        servoState={servoState}

