  fx: number; // N
  fy: number; // N
  fz: number; // N
  tx: number; // Nm
  ty: number; // Nm
  tz: number; // Nm
}

export interface EndEffectorState {
  pose: Pose3D;
  targetPose: Pose3D;
  gripperWidthMm: number; // 0 (closed) to 60 (fully open)
  isGripping: boolean;
  gripForceN: number;
  grippedObjectId: string | null;
  wrench: ForceTorqueWrench;
  tableDistanceMm: number;
}

