  /**
   * Forward Kinematics: Calculates all intermediate joint 3D positions and final TCP pose.
   * Coordinate system: Y = Up, X = Right/Forward, Z = Depth/Lateral
   */
  public forwardKinematics(anglesDeg: number[]): { positions: JointPositions3D; tcpPose: Pose3D } {
    const j1 = (anglesDeg[0] * Math.PI) / 180; // Base yaw
    const j2 = (anglesDeg[1] * Math.PI) / 180; // Shoulder pitch
    const j3 = (anglesDeg[2] * Math.PI) / 180; // Elbow pitch
    const j4 = (anglesDeg[3] * Math.PI) / 180; // Wrist pitch
    const j5 = (anglesDeg[4] * Math.PI) / 180; // Wrist roll

