    const shoulder: Vector3D = { x: 0, y: this.dims.baseHeightMm, z: 0 };

    // Cumulative pitch angles
    const theta2 = j2;
    const theta23 = j2 + j3;
    const theta234 = j2 + j3 + j4;

    // Planar reach in arm plane (r = radial distance from base axis, y = height)
    const rElbow = this.dims.upperArmLengthMm * Math.sin(theta2);
    const yElbow = shoulder.y + this.dims.upperArmLengthMm * Math.cos(theta2);

    const rWristPitch = rElbow + this.dims.forearmLengthMm * Math.sin(theta23);
    const yWristPitch = yElbow + this.dims.forearmLengthMm * Math.cos(theta23);

    const rWristRoll = rWristPitch + this.dims.wristPitchMm * Math.sin(theta234);
    const yWristRoll = yWristPitch + this.dims.wristPitchMm * Math.cos(theta234);

    const totalToolDist = this.dims.wristRollMm + this.dims.gripperOffsetMm;
    const rTcp = rWristRoll + totalToolDist * Math.sin(theta234);
    const yTcp = yWristRoll + totalToolDist * Math.cos(theta234);

    // Project planar (r, y) into 3D world with base rotation j1
    // J1 = 0 => pointing along +X axis
    const toWorld = (r: number, y: number): Vector3D => ({
      x: r * Math.cos(j1),
      y: y,
      z: -r * Math.sin(j1),
    });

    const elbow = toWorld(rElbow, yElbow);
    const wristPitch = toWorld(rWristPitch, yWristPitch);
    const wristRoll = toWorld(rWristRoll, yWristRoll);
    const tcp = toWorld(rTcp, yTcp);

