import React from 'react';
import { blackboxRecorder } from '../../services/blackboxRecorder';
import { PowerTelemetry } from '../../types/telemetry';
import { JointState } from '../../types/arm';
import { Download, Trash2, FileText, Zap, Thermometer } from 'lucide-react';

interface BlackboxPanelProps {
  power: PowerTelemetry;
  joints: JointState[];
  cycleCount: number;
}

export const BlackboxPanel: React.FC<BlackboxPanelProps> = ({ power, joints, cycleCount }) => {
  const frameCount = blackboxRecorder.getFrameCount();
  const maxTemp = joints.reduce((max, j) => Math.max(max, j.tempC), 0);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {/* Flight Recorder Buffer Status */}
      <div
        style={{
          background: 'rgba(0,0,0,0.3)',
          border: '1px solid var(--border-subtle)',
          borderRadius: '6px',
          padding: '12px',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <FileText size={16} color="var(--accent-cyan)" />
            <span className="tactical-title" style={{ fontSize: '12px', color: '#fff' }}>
              BLACKBOX TELEMETRY RECORDER
            </span>
          </div>
          <span style={{ fontSize: '11px', color: 'var(--accent-emerald)', fontWeight: 700 }}>
            BUFFERING @ 60Hz
          </span>
        </div>

        <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          RECORDED FRAMES: <b style={{ color: '#fff' }}>{frameCount}</b> / 3600 ({(frameCount / 60).toFixed(1)}s sliding window)
        </div>

        <div style={{ display: 'flex', gap: '8px', marginTop: '4px' }}>
          <button
            onClick={() => blackboxRecorder.exportJson()}
            className="tactical-btn tactical-btn-primary"
            style={{ flex: 1, height: '34px' }}
          >
            <Download size={13} /> EXPORT BLACKBOX JSON
          </button>
          <button
            onClick={() => blackboxRecorder.clear()}
            className="tactical-btn"
            style={{ height: '34px', padding: '0 12px' }}
            title="Flush Recorder Buffer"
          >
            <Trash2 size={13} /> CLEAR
          </button>
        </div>
      </div>

      {/* Power & Thermal Health Matrix */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <span className="tactical-title" style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          SUBSYSTEM HEALTH & POWER BUS:
